mapper.select:
SELECT R.ID AS id, R.ROLE_CODE AS code, R.ROLE_NAME AS name
FROM PEACH_ROLE R
WHERE R.TENANT_REF_ID = #{tenantRefId}
  AND R.APP_REF_ID = #{appRefId} AND R.AUTH_YEAR = #{year}
  AND R.ROLE_STATUS = 'ACTIVE' AND R.IS_DELETE = 0
  AND (#{keyword} = '' OR R.ROLE_CODE LIKE CONCAT('%', #{keyword}, '%')
      OR R.ROLE_NAME LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY R.ROLE_CODE, R.ID
LIMIT #{limit} OFFSET #{offset}
